class BaySpec {
  final double x, y, r;
  const BaySpec(this.x, this.y, this.r);
}

class PetalSpec {
  final double x, y, w;
  const PetalSpec(this.x, this.y, this.w);
}

class RockSpec {
  final double x, y, r;
  const RockSpec(this.x, this.y, this.r);
}

class ReedSpec {
  final double x, y, r;
  const ReedSpec(this.x, this.y, this.r);
}

class EchoSpec {
  final double x, y, r;
  const EchoSpec(this.x, this.y, this.r);
}

class CurrentSpec {
  final double x, y, r, dx, dy;
  const CurrentSpec(this.x, this.y, this.r, this.dx, this.dy);
}

class VortexSpec {
  final double x, y, r, strength;
  final bool clockwise;
  const VortexSpec(
    this.x,
    this.y,
    this.r,
    this.strength, {
    this.clockwise = true,
  });
}

class LevelSpec {
  final String name;
  final String chapter;
  final int pondVariant;
  final String blurb;
  final String hint;
  final int charges;
  final bool allowHeavy;
  final int bellX, bellY;
  final BaySpec bay;
  final List<PetalSpec> petals;
  final List<RockSpec> rocks;
  final List<ReedSpec> reeds;
  final List<EchoSpec> echoes;
  final List<CurrentSpec> currents;
  final List<VortexSpec> vortices;

  const LevelSpec({
    required this.name,
    required this.chapter,
    this.pondVariant = 0,
    required this.blurb,
    required this.hint,
    required this.charges,
    this.allowHeavy = true,
    required this.bellX,
    required this.bellY,
    required this.bay,
    required this.petals,
    required this.rocks,
    required this.reeds,
    required this.echoes,
    required this.currents,
    this.vortices = const <VortexSpec>[],
  });
}

